<?php
require_once __DIR__.'/../includes/init.php'; require_role('admin'); require_once __DIR__.'/../includes/layout.php';
$pdo=db();
$vehicles=(int)$pdo->query('SELECT COUNT(*) FROM tb_kendaraan')->fetchColumn();
$active=(int)$pdo->query("SELECT COUNT(*) FROM tb_transaksi WHERE status='masuk'")->fetchColumn();
$todayTx=(int)$pdo->query('SELECT COUNT(*) FROM tb_transaksi WHERE DATE(waktu_masuk)=CURDATE()')->fetchColumn();
$todayRevenue=(float)$pdo->query("SELECT COALESCE(SUM(biaya_total),0) FROM tb_transaksi WHERE status='keluar' AND status_pembayaran='lunas' AND DATE(waktu_keluar)=CURDATE()")->fetchColumn();
$areas=$pdo->query('SELECT id_area,nama_area,kapasitas,terisi FROM tb_area_parkir ORDER BY nama_area')->fetchAll();
$users=(int)$pdo->query('SELECT COUNT(*) FROM tb_user WHERE status_aktif=1')->fetchColumn();
$daily=$pdo->query("SELECT DATE(waktu_masuk) AS tgl,COUNT(*) AS jumlah FROM tb_transaksi WHERE waktu_masuk>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(waktu_masuk)")->fetchAll();$dailyMap=[];foreach($daily as $r)$dailyMap[$r['tgl']]=(int)$r['jumlah'];$labels=[];$values=[];for($i=6;$i>=0;$i--){$d=date('Y-m-d',strtotime("-$i days"));$labels[]=date('d M',strtotime($d));$values[]=$dailyMap[$d]??0;}
$recent=$pdo->query("SELECT t.id_parkir,k.plat_nomor,k.jenis_kendaraan,t.waktu_masuk,t.status,t.biaya_total FROM tb_transaksi t JOIN tb_kendaraan k ON k.id_kendaraan=t.id_kendaraan ORDER BY t.id_parkir DESC LIMIT 6")->fetchAll();
$chart=['type'=>'bar','legend'=>false,'data'=>['labels'=>$labels,'datasets'=>[['label'=>'Transaksi','data'=>$values,'backgroundColor'=>'#4a83f2','borderRadius'=>6,'maxBarThickness'=>28]]] ];
render_header('Dashboard Admin','dashboard'); ?>
<div class="page-intro"><div><h2>Ringkasan operasional</h2><p>Pantau kondisi parkir dan aktivitas terkini dalam satu tampilan.</p></div><a class="btn btn-primary" href="<?= h(url('admin/transaksi/index.php')) ?>">Lihat transaksi <span>→</span></a></div>
<div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-label">Kendaraan terdaftar</span><span class="stat-icon">▣</span></div><div class="stat-value"><?= number_format($vehicles) ?></div><div class="stat-foot">Data kendaraan master</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Sedang parkir</span><span class="stat-icon cyan">◷</span></div><div class="stat-value"><?= number_format($active) ?></div><div class="stat-foot">Transaksi masih aktif</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Transaksi hari ini</span><span class="stat-icon orange">⇄</span></div><div class="stat-value"><?= number_format($todayTx) ?></div><div class="stat-foot">Berdasarkan waktu masuk</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Pendapatan hari ini</span><span class="stat-icon green">Rp</span></div><div class="stat-value" style="font-size:22px"><?= h(rupiah($todayRevenue)) ?></div><div class="stat-foot">Transaksi keluar hari ini</div></article></div>
<div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Transaksi 7 hari terakhir</h2><p>Jumlah kendaraan masuk per hari</p></div><div class="chart-legend"><span><i class="legend-dot" style="background:#4a83f2"></i>Transaksi</span></div></div><div class="chart-wrap"><canvas data-chart="<?= h(json_encode($chart,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)) ?>" aria-label="Grafik transaksi tujuh hari"></canvas></div></section><section class="panel"><div class="panel-heading"><div><h2>Okupansi area</h2><p><?= count($areas) ?> area terdaftar</p></div><a class="btn btn-secondary btn-sm" href="<?= h(url('admin/area/index.php')) ?>">Kelola area</a></div><div class="panel-body"><?php if(!$areas): ?><div class="empty-state"><strong>Belum ada area</strong>Tambahkan area parkir untuk memulai.</div><?php else: foreach($areas as $a):$pct=(int)round(((int)$a['terisi']/max(1,(int)$a['kapasitas']))*100); ?><div style="margin-bottom:18px"><div class="area-top"><strong style="font-size:12px"><?= h($a['nama_area']) ?></strong><span style="font-size:11px;color:#77839a"><?= (int)$a['terisi'] ?>/<?= (int)$a['kapasitas'] ?> slot</span></div><div class="progress"><span style="width:<?= min(100,$pct) ?>%;<?= $pct>=90?'background:linear-gradient(90deg,#d8a144,#e05d6d)':'' ?>"></span></div><div class="area-foot"><span><?= $pct ?>% terisi</span><span><?= max(0,(int)$a['kapasitas']-(int)$a['terisi']) ?> tersedia</span></div></div><?php endforeach;endif; ?></div></section></div>
<section class="panel"><div class="panel-heading"><div><h2>Transaksi terbaru</h2><p>Data aktivitas parkir paling baru</p></div><a class="btn btn-secondary btn-sm" href="<?= h(url('admin/transaksi/index.php')) ?>">Semua transaksi →</a></div><div class="table-wrap"><table><thead><tr><th>No. Transaksi</th><th>Plat Nomor</th><th>Jenis</th><th>Waktu Masuk</th><th>Status</th><th>Biaya</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td class="td-main">#<?= (int)$r['id_parkir'] ?></td><td class="td-main"><?= h($r['plat_nomor']) ?></td><td><?= h(ucfirst($r['jenis_kendaraan'])) ?></td><td><?= h(tanggal($r['waktu_masuk'])) ?></td><td><?= status_badge($r['status']) ?></td><td><?= $r['biaya_total']===null?'-':h(rupiah($r['biaya_total'])) ?></td></tr><?php endforeach;if(!$recent): ?><tr><td colspan="6"><div class="empty-state">Belum ada transaksi.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php render_footer(); ?>